import type { Alert, ProtectionHistory } from "../types";
import demoData from "./demoData.json";

/*
 * Sample data for the public demo build (`npm run build:demo`), which is
 * hosted on GitHub Pages with no backend behind it. demoData.json is
 * generated by backend/scripts/generate_demo_data.py: every alert's score
 * and rationale is real output from the detection engine, and a backend
 * test fails if the file drifts from it. Only the per-day "emails checked"
 * volumes are illustrative. Offsets are stored relative to "now" so the
 * demo always looks current.
 */

const MINUTE_MS = 60_000;
const DAY_MS = 24 * 60 * MINUTE_MS;

function isoDaysAgo(daysAgo: number): string {
  return new Date(Date.now() - daysAgo * DAY_MS).toISOString().slice(0, 10);
}

export function demoAlerts(): Alert[] {
  return demoData.alerts.map((alert) => ({
    id: alert.id,
    sender_domain: alert.sender_domain,
    subject: alert.subject,
    links: alert.links,
    score: alert.score,
    rationale: alert.rationale,
    created_at: new Date(Date.now() - alert.minutes_ago * MINUTE_MS).toISOString(),
  }));
}

export function demoHistory(): ProtectionHistory {
  const history = demoData.history;
  return {
    days: history.days,
    first_scan_at: new Date(Date.now() - history.first_scan_days_ago * DAY_MS).toISOString(),
    emails_checked: history.emails_checked,
    threats_caught: history.threats_caught,
    high_risk: history.high_risk,
    links_flagged: history.links_flagged,
    daily: history.daily.map((day) => ({ date: isoDaysAgo(day.days_ago), checked: day.checked, caught: day.caught })),
    categories: history.categories,
  };
}
